INSERT INTO collection_pages VALUES('3e8ecb3a9ba6e3344ab8809d839790c043782b096fb60d4a29b2709bf75e99a4','078a398befba01e922ae99d083ccdf039e33c89af0f34d61b57e3c3062f803f5','{"hasNext":false,"items":[{"author":{"account":null,"email":"narayanan.nirmalkumar@principal.com","name":"Narayanan, Nirmalkumar"},"authoredDate":"2025-10-05T20:29:47Z","committedDate":"2025-10-05T20:29:47Z","committer":{"account":null,"email":"narayanan.nirmalkumar@principal.com","name":"Narayanan, Nirmalkumar"},"observedAt":"2026-10-08T20:32:59.005Z","repositoryId":1070395200,"sha":"ce0e75c2d9ceb0a841e51f38ad42f21f656a2d55"}],"observedAt":"2026-10-08T20:32:59.005Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/nnirmalkumar7/Recipe/commits/ce0e75c2d9ceb0a841e51f38ad42f21f656a2d55/comments","commit":{"author":{"date":"2025-10-05T20:29:47Z","email":"narayanan.nirmalkumar@principal.com","name":"Narayanan, Nirmalkumar"},"comment_count":0,"committer":{"date":"2025-10-05T20:29:47Z","email":"narayanan.nirmalkumar@principal.com","name":"Narayanan, Nirmalkumar"},"message":"Initial commit: Recipe Management System with Module Federation\n\nFeatures:\n- Complete micro-frontend architecture with Module Federation\n- 4 applications: Home (host), Customer, Creator, Admin (remotes)\n- Unit testing with Vitest + React Testing Library\n- E2E testing with Playwright + Page Object Models\n- Test coverage with Istanbul\n- TypeScript configuration\n- Comprehensive documentation\n\nTechnical Stack:\n- Vite 6.x + React 19 + TypeScript\n- Module Federation (@originjs/vite-plugin-federation)\n- Redux Toolkit for state management\n- React Router for routing\n- Modern.js for SSR support\n- Playwright for E2E testing\n- Vitest for unit testing\n\nArchitecture:\n- Home App (Port 3010): Federation host with navigation\n- Customer App (Port 3011): Recipe browsing and favorites\n- Creator Dashboard (Port 3012): Recipe creation with SSR\n- Admin Panel (Port 3001): Recipe approval and user management\n\nAll ap