t/extension.js: 193KB (minified, --production)\n- dist/extension.web.js: 190KB (minified, --production)\n- dist/chunks/: 1247KB total (37 federation chunks)\n- explorer-dates-1.3.1.vsix: 857KB (94 files)\n\nBuilt with: npm run package (vscode:prepublish → package-bundle)","tree":{"sha":"a129ce3f18c4c5cd308a73d852a92d4cf648fbac","url":"https://api.github.com/repos/incredincomp/explorer-dates/git/trees/a129ce3f18c4c5cd308a73d852a92d4cf648fbac"},"url":"https://api.github.com/repos/incredincomp/explorer-dates/git/commits/02cf351071c020bc081ba69507c4df806170a91d","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/43874843?v=4","events_url":"https://api.github.com/users/incredincomp/events{/privacy}","followers_url":"https://api.github.com/users/incredincomp/followers","following_url":"https://api.github.com/users/incredincomp/following{/other_user}","gists_url":"https://api.github.com/users/incredincomp/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/incredincomp","id":43874843,"login":"incredincomp","node_id":"MDQ6VXNlcjQzODc0ODQz","organizations_url":"https://api.github.com/users/incredincomp/orgs","received_events_url":"https://api.github.com/users/incredincomp/received_events","repos_url":"https://api.github.com/users/incredincomp/repos","site_admin":false,"starred_url":"https://api.github.com/users/incredincomp/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/incredincomp/subscriptions","type":"User","url":"https://api.github.com/users/incredincomp","user_view_type":"public"},"html_url":"https://github.com/incredincomp/explorer-dates/commit/02cf351071c020bc081ba69507c4df806170a91d","node_id":"C_kwDOP83QydoAKDAyY2YzNTEwNzFjMDIwYmMwODFiYTY5NTA3YzRkZjgwNjE3MGE5MWQ","parents":[{"html_url":"https://github.com/incredincomp/explorer-dates/commit/89b7722916cca7220e1989d733ac1bcbede61581","sha":"89b7722916cca7220e